    specialFilter([33, -2, -3, 45, 21, 109]) => 2
    """
    def is_odd(digit):
        return digit in {1, 3, 5, 7, 9}

    def first_and_last_odd(num):
        num_str = str(num)
        if len(num_str) > 1:
            return is_odd(int(num_str[0])) and is_odd(int(num_str[-1]))
        return False

    count = 0
    for num in nums:
        if num > 10 and first_and_last_odd(num):
            count += 1
    return count

